style.css:
@-moz-document regexp(".*") {
/* Base Colors & Font */
    html, body {
        background-color: #0a0a0a !important; /* Very dark background */
        color: #00ff41 !important; /* Classic Matrix Green text */
        font-family: 'Cascadia Code', 'Fira Code', 'Lucida Console', monospace !important;
        line-height: 1.6 !important;
    }

    /* Text & Headings */
    h1, h2, h3, h4, h5, h6, strong, b {
        color: #00ff41 !important;
        text-shadow: 0 0 3px #006622; /* Subtle green glow for headings */
    }

    /* Links */
    a {
        color: #00ff41 !important;
        text-decoration: none !important;
        transition: color 0.3s ease, text-shadow 0.3s ease !important;
    }
    a:hover, a:focus {
        color: #ffffff !important; /* Glowing white on hover */
        text-shadow: 0 0 5px #ffffff, 0 0 10px #ffffff !important;
    }

    /* Borders & Elements - Default Green */
    div, span, p, ul, ol, li, table, th, td,
    header, footer, nav, section, article, aside, main, form, fieldset, legend,
    input, textarea, select, button {
        border-color: #006622 !important; /* Darker green border */
        box-shadow: none !important; /* Reset default shadows */
        transition: border-color 0.3s ease, box-shadow 0.3s ease, background-color 0.3s ease !important;
    }

    /* Interactive Elements - Hover Glow */
    a, button, input[type="button"], input[type="submit"], input[type="reset"],
    input[type="text"], input[type="password"], input[type="email"], input[type="number"],
    textarea, select,
    .btn, .button, [role="button"], [tabindex]:not([tabindex="-1"]) {
        border: 1px solid #006622 !important;
        background-color: #1a1a1a !important; /* Slightly lighter dark for interactive elements */
        color: #00ff41 !important;
    }

    a:hover, button:hover, input[type="button"]:hover, input[type="submit"]:hover, input[type="reset"]:hover,
    .btn:hover, .button:hover, [role="button"]:hover,
    input[type="text"]:focus, input[type="password"]:focus, input[type="email"]:focus, input[type="number"]:focus,
    textarea:focus, select:focus {
        border-color: #ffffff !important; /* Glowing white border */
        box-shadow: 0 0 8px #ffffff, 0 0 15px #ffffff !important; /* White glow effect */
        color: #ffffff !important;
        background-color: #2a2a2a !important; /* Slightly brighter on hover/focus */
    }

    /* Specific elements that might have borders or be interactive */
    img {
        border: 1px solid #006622 !important;
        transition: border-color 0.3s ease, box-shadow 0.3s ease !important;
    }
    img:hover {
        border-color: #ffffff !important;
        box-shadow: 0 0 8px #ffffff, 0 0 15px #ffffff !important;
    }

    hr {
        border-top: 1px solid #006622 !important;
        transition: border-color 0.3s ease !important;
    }
    hr:hover {
        border-top-color: #ffffff !important;
    }

    /* Selection Highlighting */
    ::selection {
        background-color: #00ff41 !important; /* Matrix green selection */
        color: #0a0a0a !important; /* Dark text on selection */
    }
    ::-moz-selection {
        background-color: #00ff41 !important;
        color: #0a0a0a !important;
    }

    /* Scrollbars (Webkit) */
    ::-webkit-scrollbar {
        width: 12px !important;
        height: 12px !important;
    }
    ::-webkit-scrollbar-track {
        background: #1a1a1a !important; /* Dark track */
        border-radius: 10px !important;
    }
    ::-webkit-scrollbar-thumb {
        background: #006622 !important; /* Green thumb */
        border-radius: 10px !important;
        border: 2px solid #1a1a1a !important;
        transition: background 0.3s ease !important;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: #00ff41 !important; /* Brighter green on hover */
        border-color: #0a0a0a !important;
    }
    ::-webkit-scrollbar-corner {
        background: #1a1a1a !important;
    }

    /* General background for blocks/cards */
    .card, .panel, .box, .container, .wrapper {
        background-color: #1a1a1a !important;
        border: 1px solid #006622 !important;
        border-radius: 5px !important;
        padding: 15px !important;
        margin-bottom: 15px !important;
        transition: border-color 0.3s ease, box-shadow 0.3s ease !important;
    }
    .card:hover, .panel:hover, .box:hover, .container:hover, .wrapper:hover {
        border-color: #ffffff !important;
        box-shadow: 0 0 8px #ffffff, 0 0 15px #ffffff !important;
    }

    /* Tables */
    table {
        border-collapse: collapse !important;
        width: 100% !important;
    }
    th, td {
        border: 1px solid #006622 !important;
        padding: 8px !important;
        text-align: left !important;
    }
    th {
        background-color: #003311 !important; /* Darker green for table headers */
        color: #00ff41 !important;
    }
    tr:nth-child(even) {
        background-color: #111111 !important; /* Slightly different background for even rows */
    }
    tr:hover {
        background-color: #222222 !important;
        color: #ffffff !important;
    }

    /* Code blocks */
    pre, code {
        background-color: #1a1a1a !important;
        border: 1px solid #006622 !important;
        color: #00ff41 !important;
        padding: 10px !important;
        border-radius: 3px !important;
        overflow-x: auto !important;
        font-family: 'Cascadia Code', 'Fira Code', 'Lucida Console', monospace !important;
        transition: border-color 0.3s ease, box-shadow 0.3s ease !important;
    }
    pre:hover, code:hover {
        border-color: #ffffff !important;
        box-shadow: 0 0 5px #ffffff !important;
    }

    /* Forms */
    input, textarea, select {
        background-color: #1a1a1a !important;
        border: 1px solid #006622 !important;
        color: #00ff41 !important;
        padding: 8px !important;
        border-radius: 3px !important;
    }
    input::placeholder, textarea::placeholder {
        color: #009933 !important; /* Lighter green for placeholders */
    }
}
